+func (p *Path) Node() *Node {
+	switch {
+	case p.App != nil:
+		return &p.App.Node
+
+	case p.Argument != nil:
+		return p.Argument
+
+	case p.Command != nil:
+		return p.Command
+	}
+	return nil
+}
